INSERT INTO `post_schedule_change_requests` (`id`, `employee_id`, `reason`, `status`, `created_at`, `start_date`, `end_date`, `work_schedule_id`, `current_work_schedule_id`, `attachment_scr`, `notified`, `explanation`, `is_rest_day`) VALUES
(1, 77, 'change schedule', 'Approved', '2025-08-13 08:29:42', '2025-08-13', '2025-11-30', 9, 4, 'scr_689c4cf66175c.png', 0, NULL, 0),
(2, 75, 'Hi. May I request to please change the whole month of August to 8am-4:30pm shift. Apparently, the whole month shift was changed back to 7am-4pm (please see attached file) when the update occurred today and there\'s no option to choose from August 1 as the dates prior to today are frozen already. Thank you.', 'Approved', '2025-08-13 08:21:56', '2025-08-13', '2025-08-31', 9, 4, 'scr_689c4b24a708e.png', 0, NULL, 0),
(3, 89, 'approved work schedule by client 6:30am to 3:00pm', 'Approved', '2025-08-13 22:10:35', '2025-08-14', '2025-08-31', 8, 4, 'scr_689d0d5bb16cf.png', 0, NULL, 0),
(8, 52, 'My work schedule is from 9:00 a.m. to 6:00 p.m., Monday to Friday. However, in Harley, it is recorded as 7:00 a.m. to 4:00 p.m., which causes me to be tagged as late. I kindly request that my schedule in Harley be updated to reflect 9:00 a.m. to 6:00 p.m.. Thank you.', 'Declined', '2025-08-14 10:28:30', '2025-08-15', '2025-12-31', 6, 6, 'scr_689dba4eb89a6.png', 0, 'Hi, Ms. Althea! Could you please provide an attachment that shows your schedule is 7AM - 4PM on Harley? On our end, your schedule is 9AM - 6PM.', 0),
(9, 43, 'FIXED SCHEDULE EVERY WEDNESDAY 7AM-4PM', 'Approved', '2025-08-15 07:19:24', '2025-08-27', '2025-08-27', 4, 5, 'scr_689edf7c99f64.pdf', 0, NULL, 0),
(10, 43, 'FIXED SCHEDULE EVERY WEDNESDAY 7AM-4PM', 'Approved', '2025-08-15 07:18:56', '2025-08-20', '2025-08-20', 4, 5, 'scr_689edf6066d94.pdf', 0, NULL, 0),
(11, 10, 'Day Off Change due to Personal Matters.', 'Approved', '2025-08-15 09:31:56', '2025-08-18', '2025-08-18', 4, 4, 'scr_689efe8cdef57.pdf', 0, NULL, 0);
INSERT INTO `post_time_adjustment_requests` (`id`, `employee_id`, `log_date`, `current_time_in`, `current_time_out`, `requested_time_in`, `requested_time_out`, `reason`, `status`, `submitted_at`, `attachment`, `created_at`, `notified`, `deleted`) VALUES
(1, 78, '2025-07-30', '07:45:37', NULL, '07:44:00', '17:00:00', 'Forgot time logs', 'Approved', '2025-08-04 07:49:38', 'attach_688ff5924a5757.60338288.png', '2025-08-13 23:17:51', 0, 0),
(2, 47, '2025-08-01', '06:52:56', NULL, '06:52:00', '16:00:00', 'I forgot to log out. Please see the attached email to our supplier, which shows the date I was in the office', 'Approved', '2025-08-04 08:11:52', 'attach_688ffac8d60902.37719230.png', '2025-08-13 23:18:38', 0, 0),
(3, 80, '2025-08-04', NULL, NULL, '06:00:00', '15:00:00', 'Time In didn\'t go through | Decline Reason: Hi, Milbert! Can you please share with us the approval of your client for this schedule change?', 'Declined', '2025-08-04 13:45:12', 'attach_689048e8227ce1.44205672.png', '2025-08-13 23:21:25', 0, 0),
(4, 66, '2025-08-04', '09:33:26', '16:02:09', '06:50:00', NULL, 'I forgot to clock in', 'Approved', '2025-08-05 06:56:20', 'attach_68913a9457ca59.34422318.JPG', '2025-08-13 23:22:05', 0, 0),
(5, 3, '2025-08-05', '06:34:42', NULL, '06:30:00', NULL, 'PC update delays startup when I turn it on.', 'Approved', '2025-08-05 07:34:38', 'attach_6891438ea8bcb0.85594103.png', '2025-08-13 23:23:18', 1, 0),
(6, 68, '2025-08-06', '06:14:47', NULL, '06:00:00', NULL, 'When I turned on my computer and entered my password, the screen went black and then suddenly displayed the message: \'Updates are underway. Please keep your computer on.', 'Approved', '2025-08-06 06:16:47', 'attach_689282cf572036.43714634.jpeg', '2025-08-13 23:25:53', 0, 0),
(7, 13, '2025-08-07', '09:20:12', NULL, '08:00:00', '19:00:00', 'I forgot to time in, but for reference you may cross check it to the time in/out biometrics. Thank you. | Decline Reason: Hi, Rogelio! Can you please provide a proof that you were on time? You may use your web history or client conversation as proof. Moving forward, for any missed logs, please make sure to provide proof. 😊', 'Declined', '2025-08-07 09:25:15', 'attach_6894007b4623c8.13133283.png', '2025-08-13 23:30:06', 0, 0),
(8, 9, '2025-08-07', '16:01:11', '16:01:14', '06:50:00', NULL, 'for some reason it didn\'t proceed my time in and just found out when logging out.', 'Approved', '2025-08-08 06:56:30', 'attach_68952f1ed33f20.62270907.png', '2025-08-13 23:31:00', 0, 0),
(9, 72, '2025-08-11', '07:27:20', '15:59:25', NULL, '16:00:00', 'Click log out early', 'Approved', '2025-08-12 07:24:45', 'attach_689a7bbd91c651.51066693.jpg', '2025-08-13 23:35:48', 0, 0),
(10, 89, '2025-08-12', '06:10:24', NULL, '06:12:00', '15:00:00', 'no log out due to emergency reason, work later beyond shift schedule', 'Approved', '2025-08-13 06:15:18', 'attach_689bbcf6f2c790.95146241.png', '2025-08-13 23:38:33', 0, 0),
(11, 49, '2025-08-09', NULL, NULL, '06:00:00', '12:00:00', 'I forgot to log in to the Harley last Sunday from 6 AM to 12 noon. I’ll make sure it won’t happen again. | Decline Reason: Hi, Julie Anne! This is noted but kindly provide a proof that you were present during that day? You may use your web history or client conversation as proof. Thanks!', 'Declined', '2025-08-13 08:32:39', 'attach_689bdd27db4412.63221058.png', '2025-08-13 23:43:02', 0, 0),
(12, 1009, '2025-08-14', '07:41:16', NULL, '07:25:00', '16:13:00', 'test', 'Approved', '2025-08-14 08:13:41', 'attach_689d2a312c4c18.04747530.docx', '2025-08-14 00:14:11', 1, 0),
